    /// A file, flattened: the app's by its path in its folder, the kit's from the submodule's root, the browser app's, or
    /// the server's.
    static func source(_ path: String) throws -> String {
        if path.hasPrefix("kit:") { return try SearchSetParityTests.kit(String(path.dropFirst(4))) }
        if path.hasPrefix("web:") { return try SearchSetParityTests.web(String(path.dropFirst(4))) }
        if path.hasPrefix("Sources/") { return try SearchSetParityTests.server(path) }
        return try SearchSetParityTests.app(path)
    }

    /// Each pair: the app's file and line, and the mirror's file and line.
    static func expect(_ pairs: [(app: String, appLine: String, mirror: String, mirrorLine: String)]) throws {
        var read: [String: String] = [:]
        for pair in pairs {
            let app = try read[pair.app] ?? Self.source(pair.app)
            read[pair.app] = app
            let mirror = try read[pair.mirror] ?? Self.source(pair.mirror)
            read[pair.mirror] = mirror
            #expect(app.contains(NoteViewParityTests.flattened(pair.appLine)), "\(pair.app) holds \(pair.appLine)")
            #expect(mirror.contains(NoteViewParityTests.flattened(pair.mirrorLine)), "\(pair.mirror) holds \(pair.mirrorLine)")
        }
    }

