    /// Every word the server's six files write through `appWords`, each where the app's source writes it under its key.
    @Test func theAppsWordsAreTheServers() throws {
        let apps = try [Self.view, Self.network, Self.flows, Self.units, Self.chrome, Self.production, Self.geography, Self.sourcing,
                        Self.top, Self.administrations, Self.scopeBar, Self.guide].map(Self.source).joined(separator: " ")
        let servers = try [Self.archivalServer, Self.networkServer, Self.flowsServer, Self.libraryServer, Self.seriesServer, Self.bundleServer]
            .map(Self.source).joined(separator: " ")
        let pattern = try NSRegularExpression(pattern: #"appWords\("((?:[^"\\]|\\.)*)", "((?:[^"\\]|\\.)*)"\)"#)
        let words = pattern.matches(in: servers, range: NSRange(servers.startIndex..., in: servers)).map { match in
            (key: String(servers[Range(match.range(at: 1), in: servers)!]), value: String(servers[Range(match.range(at: 2), in: servers)!]))
        }
        #expect(words.count > 250, "the server writes \(words.count) of the app's words")
        for word in words {
            #expect(NoteViewParityTests.writes(apps, word.key, word.value), "the app writes \(word.key) as \(word.value)")
        }
    }

